#include <stdio.h>

#define MAXN 1005
#define INF 1e30

int main(void) {
    int n;
    double D;
    if (scanf("%d %lf", &n, &D) != 2) return 0;

    static double p[MAXN], c[MAXN], dp[MAXN];

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &p[i], &c[i]);
    }

    /* dp[i] = tempo mínimo para chegar à posição da bateria i,
       tendo trocado para a bateria i ao chegar lá */
    dp[0] = 0.0;
    for (int i = 1; i < n; i++) dp[i] = INF;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] == INF) continue;
            double d = p[i] - p[j];
            double t = dp[j] + d * d / c[j]; /* tempo mínimo = d^2 / C, com V = C/d */
            if (t < dp[i]) dp[i] = t;
        }
    }

    /* resposta: de qualquer bateria, percorrer o trecho final até D */
    double ans = INF;
    for (int j = 0; j < n; j++) {
        if (dp[j] == INF) continue;
        double d = D - p[j];
        double t = dp[j] + d * d / c[j];
        if (t < ans) ans = t;
    }

    printf("%.3f\n", ans);
    return 0;
}
